{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret har den korrekte hovedkonklusion: arbejdsophør giver ikke i sig selv ret. Det tilføjer dog en forkert eller uunderbygget påstand om, at UDK vurderer, om ansøgeren kan efterkomme krav om aktivering og jobsøgning i forbindelse med kontanthjælp eller førtidspension. Det står ikke i kilderne. Samtidig mangler svaret kernen i UDK's vurdering: arbejdets karakter holdt op mod funktionsnedsættelsen og muligheden for andre typer arbejde."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Ingen af de tre kritiske elementer er med. Svaret nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen. Det nævner ikke, at sagens øvrige oplysninger bruges til at vurdere andre typer arbejde. Det nævner heller ikke skånehensyn eller mindre arbejdsomfang. Det siger kun generelt, at UDK ser på arbejdsmarkedsmæssige muligheder."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret besvarer første del af spørgsmålet (ikke i sig selv ret). Anden del, hvad UDK vurderer ved arbejdsophør, besvares kun med generiske udsagn og irrelevant tekst om aktivering og jobsøgning ved kontanthjælp og førtidspension. Den specifikke vurdering ved arbejdsophør mangler."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en uunderbygget regel: UDK skulle vurdere, om ansøgeren kan efterkomme krav til aktivering og jobsøgning ved kontanthjælp eller førtidspension. Det har ingen støtte i § 7, stk. 3, bekendtgørelsen eller vejledningen. Påstanden om, at begrænsningen skal være 'så stor, at den i sig selv berettiger til tillægget', er også en uunderbygget formulering."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret fastholder, at arbejdsophøret ikke i sig selv afgør retten. Men det udtrykker ikke, at oplysningen om ophør er udgangspunkt for en nærmere vurdering af arbejdets karakter og andre jobmuligheder. Det nævner heller ikke, at ikke-fysisk belastende arbejde er et eksempel og ikke en selvstændig betingelse."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Konklusionen om, at arbejdsophør ikke i sig selv er nok, og at der kræves en varig og særlig stor begrænsning, følger af de trin, som svaret selv angiver."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret fremstiller aktiverings- og jobsøgningsvurderingen som noget, UDK 'også vil tage stilling til'. Det gør en uunderbygget vurdering til en fast regel. Kravet om varig funktionsnedsættelse med særlig stor betydning gengives nogenlunde, men er ikke knyttet til kilden."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret behandler situationen, hvor ansøgeren har stoppet arbejde på grund af funktionsnedsættelsen, og siger, at det ikke i sig selv giver ret. Det gengiver ikke vurderingen af arbejdets karakter i forhold til funktionsnedsættelsen eller vurderingen af gener og skånebehov."
    },
    "A23": {
      "label": "no",
      "reason": "Svaret nævner ikke, at UDK vurderer, om ansøgeren kan varetage andre typer arbejde, eventuelt med skånehensyn eller i mindre omfang. Det nævner kun generelt evnen til at opnå og beholde et arbejde."
    }
  },
  "overall_notes": "Svaret har den rigtige hovedkonklusion, men det er generisk og mangler vejledningens centrale vurdering. Det tilføjer desuden uunderbygget indhold om aktivering og jobsøgning og citerer ingen kilder."
}

